import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
empty = {t for (t,) in con.execute("select name from sqlite_master where type='table'")
         if con.execute(f'select count(*) from "{t}"').fetchone()[0] == 0}
print("EMPTY TABLES (%d):" % len(empty), sorted(empty))
print("--- UNWRITABLE derivation (CLAUDE.md s4 snippet, verbatim logic) ---")
n=0
for (t,) in con.execute("select name from sqlite_master where type='table'"):
    dead = {f[3] for f in con.execute(f'PRAGMA foreign_key_list("{t}")') if f[2] in empty}
    for c in con.execute(f'PRAGMA table_info("{t}")'):
        if c[1] in dead and c[3]:
            print(f"UNWRITABLE  {t}.{c[1]} -> empty table"); n+=1
print("UNWRITABLE count:", n)
print("--- composite FKs anywhere (multi-column FK would defeat the per-column derivation) ---")
comp=[]
for (t,) in con.execute("select name from sqlite_master where type='table'"):
    fks={}
    for f in con.execute(f'PRAGMA foreign_key_list("{t}")'):
        fks.setdefault(f[0],[]).append(f)
    for k,v in fks.items():
        if len(v)>1: comp.append((t,k,len(v)))
print("composite FK groups:", comp if comp else "[NULL: all tables, all foreign keys — examined, nothing found]")
